<?php
namespace App\Http\Controllers;
use App\Models\{Equipment,School};
use Illuminate\Http\Request;
class EquipmentController extends Controller { public function index(Request $r){$q=Equipment::with('school')->latest();if($r->user()->isDirector())$q->where('unidad_educativa_id',$r->user()->school_id);return view('equipment.index',['equipment'=>$q->paginate(15)]);} public function create(){return view('equipment.form',['item'=>new Equipment,'schools'=>School::where('activo',true)->orderBy('nombre')->get()]);} public function store(Request $r){Equipment::create($this->data($r));return redirect()->route('equipment.index')->with('success','Equipo registrado.');} public function edit(Equipment $equipment){return view('equipment.form',['item'=>$equipment,'schools'=>School::where('activo',true)->orderBy('nombre')->get()]);} public function update(Request $r,Equipment $equipment){$equipment->update($this->data($r,$equipment->id));return redirect()->route('equipment.index')->with('success','Equipo actualizado.');} private function data(Request $r,$id=null){return $r->validate(['school_id'=>'required|exists:unidades_educativas,id','asset_code'=>'required|max:50|unique:equipos,codigo_patrimonial,'.$id,'type'=>'required|in:computer,printer,monitor,router,network,other','brand'=>'nullable|max:100','model'=>'nullable|max:100','serial_number'=>'nullable|max:100','location'=>'nullable|max:150','status'=>'required|in:operational,under_repair,out_of_service','notes'=>'nullable|max:2000']);} }
